;; Converting a vector to a set:

(reduce conj #{} [:a :b :c])
;; => #{:a :c :b}

;; Transform key/value pairs
(reduce (fn [acc [k v]]
          (assoc acc (str (name k)) v))
        {}
        [[:a 1] [:b 2] [:c 3]])
;;=> {"a" 1, "b" 2, "c" 3}

(reduce (fn [acc [k v]]
          (assoc acc (str "k" k) (* v 2)))
        {}
        (partition 2 (range 10)))
;;=> {"k0" 2, "k2" 6, "k4" 10, "k6" 14, "k8" 18}

;;practical example

(def entries [{:month 1 :val 12}
              {:month 2 :val 3}
              {:month 3 :val 32}
              {:month 4 :val 18}
              {:month 5 :val 32}
              {:month 6 :val 62}
              {:month 7 :val 12}
              {:month 8 :val 142}
              {:month 9 :val 52}
              {:month 10 :val 18}
              {:month 11 :val 23}
              {:month 12 :val 56}])

(apply max (map
            #(:val %)
            entries))
;;return 142
;;this translates into (max 12 3 32 18 32 62 12 142 52 18 23 56)

;; make a struct 'goods'. it assumes that every goods has
;; its id number and price.
(defstruct goods :id :price)

;; generate data.
(def data (map #(struct goods %1 %2)
	       (shuffle (range 0 10)) 
               (shuffle
	          (into (range 100 500 100)
			(range 100 500 100)))))

(defn comp-goods-price
  "a compare function by :price of the struct 'goods.' the sort order 
   is that the lower price is superior to the higher one and if the 
   price is same, the lower id is superior to the higher one."
  [el1 el2]
  (if (or  (< (:price el1) (:price el2))
           (and (= (:price el1) (:price el2)) (< (:id el1) (:id el2))))
    true
    false))

;; The shuffle will cause your results to differ.
data   
;;=> ({:id 1, :price 300} {:id 6, :price 100} 
;;    {:id 3, :price 100} {:id 4, :price 400}
;;    {:id 0, :price 300} {:id 2, :price 200} 
;;    {:id 5, :price 200} {:id 8, :price 400})

(sort (comp comp-goods-price) data)
;;=> ({:id 3, :price 100} {:id 6, :price 100} 
;;    {:id 2, :price 200} {:id 5, :price 200} 
;;    {:id 0, :price 300} {:id 1, :price 300}
;;    {:id 4, :price 400} {:id 8, :price 400})

(sort-by :price < data) ; compare this with the above.
;;=> ({:id 6, :price 100} {:id 3, :price 100} 
;;    {:id 2, :price 200} {:id 5, :price 200} 
;;    {:id 1, :price 300} {:id 0, :price 300} 
;;    {:id 4, :price 400} {:id 8, :price 400})

;; Yet another example of 'comp' by PriorityBlockingQueue.

(import [java.util.concurrent PriorityBlockingQueue])
;; java.util.concurrent.PriorityBlockingQueue

(def pqdata (new PriorityBlockingQueue 8
		 (comp comp-goods-price)))
;; #'user/pqdata

(doseq [x data] (.add pqdata x))
;;=> nil

(dotimes [_ 8] (println (.poll pqdata)))
;;  {:id 3, :price 100}
;;  {:id 6, :price 100}
;;  {:id 2, :price 200}
;;  {:id 5, :price 200}
;;  {:id 0, :price 300}
;;  {:id 1, :price 300}
;;  {:id 4, :price 400}
;;  {:id 8, :price 400}
;;=> nil

;; The `:while` modifier triggers the inner-most loop to be aborted.
;; (to break out of the inner most loop).

(doseq [a (range 5)
        b (range 5)
        :while (even? b) ;; when be fails to be even, then break out of b loop
       ]
  (println {:a a :b b})
;; Output
{:a 0, :b 0}
{:a 1, :b 0}
{:a 2, :b 0}
{:a 3, :b 0}
{:a 4, :b 0}

notes.body:
The problem `loop` is trying to solve is that recursively calling the same function on the JVM is expensive and doesn't scale. It might work if your data structure is a thousand levels deep but it will fail badly with a depth of millions of levels.

What is not possible on the JVM is what is called "tail-call optimization". `loop` is like a `while` loop in java, except that if you don't call `recur` (with the correct number of arguments) the loop will exit. In while-loop terms, `recur` avoids that a `break` statement is executed.

<pre>int counter = 0;
while (true) {
   if (counter &lt; 10) {
      // recur
      counter = inc(counter);
   } else {
      break;
   }
}
</pre>

In that sense `loop` is a recur target as in "target for recursion".

