;; Use union to merge sets of elements
(use 'clojure.set)
(merge-with union
            {:a #{1 2 3},   :b #{4 5 6}}
            {:a #{2 3 7 8}, :c #{1 2 3}})

;;=> {:c #{1 2 3}, :a #{1 2 3 7 8}, :b #{4 5 6}}

;; Use merge-with and merge to merge values that are one level deep maps.

(merge-with merge {:x {:y 1}} {:x {:z 2}})
;;=> {:x {:z 2, :y 1}}

;; Deeper maps are not merged:
(merge-with merge {:x {:y {:a 1}}} {:x {:y {:b 2}}})
;;=>{:x {:y {:b 2}}}

;;Use into to avoid losing the shape (i.e. a vector) of the original data:
(merge-with into
	  {"Lisp" ["Common Lisp" "Clojure"]
	   "ML" ["Caml" "Objective Caml"]}
	  {"Lisp" ["Scheme"]
	   "ML" ["Standard ML"]})
;;=> {"Lisp" ["Common Lisp" "Clojure" "Scheme"], "ML" ["Caml" "Objective Caml" "Standard ML"]}

;;No need to use type-specific verbs such as union:
(merge-with into
            {:a #{1 2 3},   :b #{4 5 6}}
            {:a #{2 3 7 8}, :c #{1 2 3}})
;;=> {:c #{1 2 3}, :a #{1 2 3 7 8}, :b #{4 5 6}}

;; We may dig into multiple levels with `update-in`:
(def player1 {:name "Player 1" :attribs {:str 10 :int 11 :wis 9}})

(update-in player1 [:attribs :str] inc)
;; {:name "Player 1", :attribs {:str 11, :int 11, :wis 9}}

(update-in player1 [:attribs :str] * 2)
;; {:name "Player 1", :attribs {:str 20, :int 11, :wis 9}}

;; We can see one level via `update`...

(update player1 :attribs #(update % :str inc))
;; {:name "Player 1", :attribs {:str 11, :int 11, :wis 9}}

