;; from http://www.braveclojure.com/functional-programming/

(merge {:a 1} nil)   ;=> {:a 1}
(merge nil {:a 1})   ;=> {:a 1}
(merge nil nil)      ;=> nil

;; `merge` can be used to support the setting of default values
(merge {:foo "foo-default" :bar "bar-default"} 
       {:foo "custom-value"})
;;=> {:foo "custom-value" :bar "bar-default"}

;; This is useful when a function has a number of options
;; with default values.
(defn baz [& options]
   (let [options (merge {:opt1 "default-1" :opt2 "default-2"} 
                        (first options))]
      options))

(baz {:opt1 "custom-1" :opt3 "custom-3"})
;;=> {:opt3 "custom-3" :opt1 "custom-1 :opt2 "default-2"}

;; This could be handy in certain situations.

(defn reverse-merge
  "Same as `merge` but works in reverse order."
  [& maps]
  (apply merge (reverse maps)))

(reverse-merge {:foo "FOO"}
               {:foo "---" :bar "BAR"}
               {:bar "---" :baz "BAZ"})
;; => {:bar "BAR", :baz "BAZ", :foo "FOO"}

;; If an empty sequence is used as keys, the whole structure is returned.
(get-in {:a 1 :b 2} [])
;;=> {:a 1, :b 2}
(get-in {:a 1, :b 2} '())
;;=> {:a 1, :b 2}

;; nil also counts as an empty sequence!
(get-in {:a 1 :b 2} nil)
;;=> {:a 1, :b 2}

;; Be careful if you use a nill-able key sequence with not-found value.
;; This can be a source of bug.
(get-in {:a 1 :b 2} nil :nothing)
;;=> {:a 1, :b 2}

